"""Semantics module — defines build_report() coroutine."""

import json
import gel


async def _introspect(client: gel.AsyncIOClient) -> dict:
    """Introspect schema types and pointers."""
    result = {}
    type_names = [
        "default::Sample",
        "default::Measurement",
        "default::Assay",
        "default::Calibration",
        "default::Certificate",
        "default::Batch",
    ]
    short_names = {
        "default::Sample": "Sample",
        "default::Measurement": "Measurement",
        "default::Assay": "Assay",
        "default::Calibration": "Calibration",
        "default::Certificate": "Certificate",
        "default::Batch": "Batch",
    }

    rows = await client.query_json("""
        WITH
          types := (SELECT schema::ObjectType FILTER .name IN array_unpack(<array<str>>$names)),
        SELECT types {
            name,
            abstract,
            pointers: {
                name,
                cardinality,
                required,
                computed := exists .expr,
                target_name := .target.name
            } FILTER .name NOT IN {'id', '__type__'}
        } ORDER BY .name;
    """, names=type_names)

    data = json.loads(rows)
    for t in data:
        sn = short_names[t["name"]]
        pointers = {}
        for p in t["pointers"]:
            pointers[p["name"]] = {
                "cardinality": p["cardinality"],
                "required": p["required"],
                "computed": p["computed"],
                "target": p["target_name"],
            }
        result[sn] = {
            "abstract": t["abstract"],
            "pointers": pointers,
        }

    return result


async def _introspect_link_properties(client: gel.AsyncIOClient) -> dict:
    """Introspect link properties on Batch.samples."""
    rows = await client.query_json("""
        SELECT schema::Pointer {
            name,
            cardinality,
            required,
            target_name := .target.name,
        } FILTER .name = 'position' AND .source.name = 'samples';
    """)
    data = json.loads(rows)
    lp = {}
    if data:
        item = json.loads(rows)[0]
        lp = {
            "cardinality": item["cardinality"],
            "required": item["required"],
            "target": item["target_name"],
        }
    return {"Batch.samples": {"position": lp}}


async def _build_defaults(client: gel.AsyncIOClient) -> dict:
    """Build the defaults section of the report."""
    # Create the batch of 4 samples
    result = await client.query_single_json("""
        WITH
            inserted := (
                INSERT Sample {
                    label := 'Alpha-01',
                    grams := 1.5
                },
                INSERT Sample {
                    label := 'Bravo-02',
                    grams := 2.25
                },
                INSERT Sample {
                    label := 'Charlie-03',
                    grams := 3.0
                },
                INSERT Sample {
                    label := 'Delta-04',
                    grams := 4.75
                }
            ),
        SELECT {
            batch_insert_size := count(inserted),
            distinct_intake_at_in_batch := count(DISTINCT inserted.intake_at),
            distinct_intake_ref_in_batch := count(DISTINCT inserted.intake_ref),
        };
    """)
    batch_info = json.loads(result)

    # Create the late sample in a separate statement
    await client.query("""
        INSERT Sample {
            label := 'Echo-05',
            grams := 5.5
        };
    """)

    # Get Echo-05's intake_at and the batch's intake_at for comparison
    late_vs_batch = await client.query_single_json("""
        WITH
            batch_sample := (SELECT Sample FILTER .label = 'Alpha-01'),
            late_sample := (SELECT Sample FILTER .label = 'Echo-05'),
        SELECT {
            late_not_before := late_sample.intake_at >= batch_sample.intake_at,
        };
    """)
    late_info = json.loads(late_vs_batch)

    # Get the Delta-04 sample's intake_at and intake_ref before update
    before_update = await client.query_single_json("""
        SELECT Sample {
            intake_at,
            intake_ref,
        } FILTER .label = 'Delta-04';
    """)
    before = json.loads(before_update)

    # Update Delta-04 to Zulu-99
    await client.query("""
        UPDATE Sample
        FILTER .label = 'Delta-04'
        SET {
            label := 'Zulu-99',
            grams := 9.0
        };
    """)

    # Get the same sample's intake_at and intake_ref after update
    after_update = await client.query_single_json("""
        SELECT Sample {
            intake_at,
            intake_ref,
        } FILTER .label = 'Zulu-99';
    """)
    after = json.loads(after_update)

    # Try to update intake_at (read-only) and capture the error
    readonly_rejected = False
    error_class = ""
    error_message = ""
    try:
        await client.query("""
            UPDATE Sample
            FILTER .label = 'Zulu-99'
            SET {
                intake_at := std::datetime_current()
            };
        """)
    except gel.GelError as e:
        readonly_rejected = True
        error_class = type(e).__name__
        error_message = str(e)
    except Exception as e:
        readonly_rejected = True
        error_class = type(e).__name__
        error_message = str(e)

    return {
        "batch_insert_size": batch_info["batch_insert_size"],
        "distinct_intake_at_in_batch": batch_info["distinct_intake_at_in_batch"],
        "distinct_intake_ref_in_batch": batch_info["distinct_intake_ref_in_batch"],
        "intake_at_unchanged_after_update": before["intake_at"] == after["intake_at"],
        "intake_ref_unchanged_after_update": before["intake_ref"] == after["intake_ref"],
        "late_intake_at_not_before_batch": late_info["late_not_before"],
        "readonly_update_rejected": {
            "rejected": readonly_rejected,
            "error_class": error_class,
            "error_message": error_message,
        },
    }


async def _build_computed(client: gel.AsyncIOClient) -> dict:
    """Build the computed section of the report."""
    # Read label_key before update (Delta-04)
    before = await client.query_single_json("""
        SELECT Sample {
            label_key,
        } FILTER .label = 'Delta-04';
    """)
    before_data = json.loads(before)

    # Read computed values from Alpha-01 before measurements exist
    alpha_before = await client.query_single_json("""
        SELECT Sample {
            assay_count,
            measurement_count,
            total_value,
        } FILTER .label = 'Alpha-01';
    """)
    alpha_before_data = json.loads(alpha_before)

    # Create measurements
    await client.query("""
        WITH
            alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
            bravo := (SELECT Sample FILTER .label = 'Bravo-02'),
            charlie := (SELECT Sample FILTER .label = 'Charlie-03'),
        INSERT Assay {
            code := 'A1',
            sample := alpha,
            value := 10.0
        };
    """)
    await client.query("""
        WITH
            alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
        INSERT Assay {
            code := 'A2',
            sample := alpha,
            value := 2.5
        };
    """)
    await client.query("""
        WITH
            bravo := (SELECT Sample FILTER .label = 'Bravo-02'),
        INSERT Assay {
            code := 'A3',
            sample := bravo,
            value := 7.25
        };
    """)
    await client.query("""
        WITH
            alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
        INSERT Calibration {
            code := 'C1',
            sample := alpha,
            bias := 0.5
        };
    """)
    await client.query("""
        WITH
            charlie := (SELECT Sample FILTER .label = 'Charlie-03'),
        INSERT Calibration {
            code := 'C2',
            sample := charlie,
            bias := -1.25
        };
    """)

    # Read computed values from Alpha-01 after measurements exist
    alpha_after = await client.query_single_json("""
        SELECT Sample {
            assay_count,
            measurement_count,
            total_value,
        } FILTER .label = 'Alpha-01';
    """)
    alpha_after_data = json.loads(alpha_after)

    # Read label_key after update
    after = await client.query_single_json("""
        SELECT Sample {
            label_key,
        } FILTER .label = 'Zulu-99';
    """)
    after_data = json.loads(after)

    # Check age non-negative for all samples
    age_check = await client.query_single_json("""
        SELECT {
            all_non_negative := all(
                (SELECT Sample.age) >= <duration>'0s'
            ),
        };
    """)
    age_check_data = json.loads(age_check)

    # Check age_difference_matches_intake_difference in one statement
    age_match = await client.query_single_json("""
        WITH
            alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
            echo := (SELECT Sample FILTER .label = 'Echo-05'),
        SELECT {
            matches := (
                (echo.age - alpha.age) = (echo.intake_at - alpha.intake_at)
            ),
        };
    """)
    age_match_data = json.loads(age_match)

    return {
        "label_key_before_update": before_data["label_key"],
        "label_key_after_update": after_data["label_key"],
        "alpha_assay_count_before": alpha_before_data["assay_count"],
        "alpha_measurement_count_before": alpha_before_data["measurement_count"],
        "alpha_total_value_before": alpha_before_data["total_value"],
        "alpha_assay_count_after": alpha_after_data["assay_count"],
        "alpha_measurement_count_after": alpha_after_data["measurement_count"],
        "alpha_total_value_after": alpha_after_data["total_value"],
        "age_non_negative": age_check_data["all_non_negative"],
        "age_difference_matches_intake_difference": age_match_data["matches"],
    }


async def _build_volatility(client: gel.AsyncIOClient) -> dict:
    """Build the volatility section of the report."""
    # Probe 1: Try to create a schema-level computed with a volatile expression
    schema_rejected = False
    schema_error_class = ""
    schema_error_message = ""

    try:
        await client.query("""
            ALTER TYPE Sample {
                CREATE PROPERTY volatile_probe := std::datetime_current();
            };
        """)
    except gel.GelError as e:
        schema_rejected = True
        schema_error_class = type(e).__name__
        schema_error_message = str(e)
    except Exception as e:
        schema_rejected = True
        schema_error_class = type(e).__name__
        schema_error_message = str(e)

    # Probe 2: Cartesian product with volatile expression
    cartesian_rejected = False
    cartesian_error_class = ""
    cartesian_error_message = ""

    try:
        await client.query("""
            SELECT (Sample, std::datetime_current());
        """)
    except gel.GelError as e:
        cartesian_rejected = True
        cartesian_error_class = type(e).__name__
        cartesian_error_message = str(e)
    except Exception as e:
        cartesian_rejected = True
        cartesian_error_class = type(e).__name__
        cartesian_error_message = str(e)

    # Verify schema is unchanged: exactly 6 object types
    type_count = await client.query_single_json("""
        SELECT count(
            schema::ObjectType FILTER .name LIKE 'default::%'
        );
    """)
    type_count_data = json.loads(type_count)

    # Verify migration history is in sync
    migration_status = await client.query_single_json("""
        SELECT schema::Migration {
            name,
            done,
        } ORDER BY .name;
    """)
    migration_data = json.loads(migration_status)

    # Check that there's no volatile_probe on Sample
    sample_pointers = await client.query_single_json("""
        SELECT count(
            schema::Pointer FILTER .name = 'volatile_probe'
            AND .source.name = 'default::Sample'
        );
    """)
    probe_count = json.loads(sample_pointers)

    schema_unchanged = (type_count_data == 6 and probe_count == 0)

    return {
        "schema_computed_volatile": {
            "rejected": schema_rejected,
            "error_class": schema_error_class,
            "error_message": schema_error_message,
        },
        "cartesian_volatile": {
            "rejected": cartesian_rejected,
            "error_class": cartesian_error_class,
            "error_message": cartesian_error_message,
        },
        "schema_unchanged_after_probe": schema_unchanged,
    }


async def _build_samples(client: gel.AsyncIOClient) -> list:
    """Build the samples array."""
    rows = await client.query_json("""
        SELECT Sample {
            label,
            label_key,
            assay_count,
            measurement_count,
            total_value,
            has_certificate := exists(.certificate),
            batch_codes := (SELECT .batches.code ORDER BY .batches.code),
        } ORDER BY .label;
    """)
    return json.loads(rows)


async def _build_batch(client: gel.AsyncIOClient) -> dict:
    """Build the batch section."""
    rows = await client.query_json("""
        SELECT Batch {
            code,
            sample_count,
            members := (
                SELECT .samples {
                    label,
                    @position,
                } ORDER BY @position
            ),
        };
    """)
    data = json.loads(rows)
    if data:
        return data[0]
    return {}


async def _cleanup(client: gel.AsyncIOClient) -> None:
    """Delete all pre-existing objects of the declared types."""
    await client.query("""
        DELETE Calibration;
        DELETE Assay;
        DELETE Certificate;
        DELETE Batch;
        DELETE Sample;
    """)


async def build_report() -> dict:
    """Build the complete report as a dict."""
    client = gel.create_async_client()
    try:
        await _cleanup(client)

        report = {}

        # Introspection (no data dependency)
        report["introspection"] = await _introspect(client)
        report["link_properties"] = await _introspect_link_properties(client)

        # Defaults section (creates samples, does update, probes read-only)
        report["defaults"] = await _build_defaults(client)

        # Computed section (creates measurements, reads computed values)
        report["computed"] = await _build_computed(client)

        # Create Certificate and Batch
        await client.query("""
            WITH
                alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
            INSERT Certificate {
                serial := 'CERT-ALPHA',
                sample := alpha,
            };
        """)
        await client.query("""
            WITH
                alpha := (SELECT Sample FILTER .label = 'Alpha-01'),
                bravo := (SELECT Sample FILTER .label = 'Bravo-02'),
                charlie := (SELECT Sample FILTER .label = 'Charlie-03'),
            INSERT Batch {
                code := 'BATCH-1',
                samples := (
                    (SELECT alpha { @position := 1 }),
                    (SELECT bravo { @position := 2 }),
                    (SELECT charlie { @position := 3 })
                ),
            };
        """)

        # Samples and batch sections
        report["samples"] = await _build_samples(client)
        report["batch"] = await _build_batch(client)

        # Volatility section (last, probes without leaving residue)
