        batch_codes_data = json.loads(batch_codes_rows)
        batch_codes_map = {item["label"]: item["batch_codes"] for item in batch_codes_data}

        for s in samples_data:
            s["batch_codes"] = batch_codes_map.get(s["label"], [])

